void main() {
  // Create a list of fruits
  List<String> fruits = ['Apple', 'Banana', 'Mango'];

  // Add an item
  fruits.add('Orange');

  // Access items
  print(fruits[0]); // Apple

  // Loop through the list
  for (String fruit in fruits) {
    print(fruit);
  }
}

