void main() {
  // Map of student and marks
  Map<String, int> studentMarks = {
    'Alice': 85,
    'Bob': 92,
    'Charlie': 78
  };

  // Access value
  print(studentMarks['Bob']); // 92

  // Add new entry
  studentMarks['David'] = 88;

  // Loop through map
  studentMarks.forEach((key, value) {
    print('$key scored $value');
  });
}
